import sys
import json
import pandas as pd
import numpy as np

def to_float(x):
    if x is None:
        return None
    try:
        if isinstance(x, (np.floating, np.integer)):
            x = x.item()
        if isinstance(x, float) and (np.isnan(x) or np.isinf(x)):
            return None
        return float(x)
    except Exception:
        return None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # --- Totals ---
    rev_tw_sum = df['Revenue_TW'].sum(skipna=True)
    rev_lw_sum = df['Revenue_LW'].sum(skipna=True)
    rev_ly_sum = df['Revenue_LY'].sum(skipna=True)
    units_tw_sum = df['Units_TW'].sum(skipna=True)
    units_lw_sum = df['Units_LW'].sum(skipna=True)
    orders_tw_sum = df['Orders_TW'].sum(skipna=True)
    orders_lw_sum = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(to_float(rev_tw_sum), 2) if to_float(rev_tw_sum) is not None else None,
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(to_float(rev_lw_sum), 2) if to_float(rev_lw_sum) is not None else None,
        "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": round(to_float(rev_ly_sum), 2) if to_float(rev_ly_sum) is not None else None,
        "formula": "sum(Revenue_LY)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw_sum),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(units_lw_sum),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw_sum),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(orders_lw_sum),
        "formula": "sum(Orders_LW)"
    })

    # Total WoW pct
    if rev_lw_sum and not np.isnan(rev_lw_sum) and rev_lw_sum != 0:
        wow_total = (rev_tw_sum - rev_lw_sum) / rev_lw_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(to_float(wow_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    # Total YoY pct
    if rev_ly_sum and not np.isnan(rev_ly_sum) and rev_ly_sum != 0:
        yoy_total = (rev_tw_sum - rev_ly_sum) / rev_ly_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(to_float(yoy_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # --- Top 3 entities by Revenue_TW ---
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(3)
    for _, row in top_rev.iterrows():
        val = to_float(row['Revenue_TW'])
        if val is not None:
            facts.append({
                "entity": str(row['Entity']),
                "metric": "revenue",
                "period": "TW",
                "value": round(val, 2),
                "formula": "Revenue_TW"
            })

    # --- Top 3 WoW gainers ---
    wow_valid = df.dropna(subset=['WoW_Pct'])
    wow_valid = wow_valid[np.isfinite(wow_valid['WoW_Pct'])]
    top_wow_gain = wow_valid.sort_values('WoW_Pct', ascending=False).head(3)
    for _, row in top_wow_gain.iterrows():
        val = to_float(row['WoW_Pct'])
        if val is not None:
            facts.append({
                "entity": str(row['Entity']),
                "metric": "revenue",
                "period": "WoW",
                "value": round(val, 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

    # --- Top 3 WoW decliners ---
    top_wow_decl = wow_valid.sort_values('WoW_Pct', ascending=True).head(3)
    for _, row in top_wow_decl.iterrows():
        val = to_float(row['WoW_Pct'])
        if val is not None:
            facts.append({
                "entity": str(row['Entity']),
                "metric": "revenue",
                "period": "WoW",
                "value": round(val, 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

    # --- Top 3 YoY gainers ---
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    yoy_valid = yoy_valid[np.isfinite(yoy_valid['YoY_Pct'])]
    top_yoy_gain = yoy_valid.sort_values('YoY_Pct', ascending=False).head(3)
    for _, row in top_yoy_gain.iterrows():
        val = to_float(row['YoY_Pct'])
        if val is not None:
            facts.append({
                "entity": str(row['Entity']),
                "metric": "revenue",
                "period": "YoY",
                "value": round(val, 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

    # --- Top 3 YoY decliners ---
    top_yoy_decl = yoy_valid.sort_values('YoY_Pct', ascending=True).head(3)
    for _, row in top_yoy_decl.iterrows():
        val = to_float(row['YoY_Pct'])
        if val is not None:
            facts.append({
                "entity": str(row['Entity']),
                "metric": "revenue",
                "period": "YoY",
                "value": round(val, 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
